using System;using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Forms{public class MedicineEditorForm:Form{TextBox fa=new TextBox(),en=new TextBox(),bar=new TextBox(),cat=new TextBox(),batch=new TextBox(),maker=new TextBox();NumericUpDown stock=new NumericUpDown(),min=new NumericUpDown(),buy=new NumericUpDown(),sell=new NumericUpDown();DateTimePicker expiry=new DateTimePicker();public Medicine Result{get;private set;}public MedicineEditorForm(Medicine m=null){Text=Localization.Persian?"ثبت / ویرایش دارو":"Add / edit medicine";Size=new Size(650,600);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(235,247,252);Font=Theme.Font(9);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;Build(m);}void Build(Medicine m){string[] names=Localization.Persian?new[]{"نام فارسی","نام انگلیسی","بارکد","دسته‌بندی","موجودی","حداقل موجودی","قیمت خرید","قیمت فروش","تاریخ انقضا","Batch / Lot","تولیدکننده"}:new[]{"Persian name","English name","Barcode","Category","Stock","Minimum stock","Buy price","Sell price","Expiry","Batch / Lot","Manufacturer"};Control[] inputs={fa,en,bar,cat,stock,min,buy,sell,expiry,batch,maker};for(int i=0;i<inputs.Length;i++){var l=new Label{Text=names[i],Left=35,Top=30+i*42,Width=160,Height=28,ForeColor=Theme.Navy,TextAlign=ContentAlignment.MiddleRight};inputs[i].SetBounds(205,30+i*42,380,30);Controls.Add(l);Controls.Add(inputs[i]);}stock.Maximum=min.Maximum=100000;buy.Maximum=sell.Maximum=1000000000;buy.ThousandsSeparator=sell.ThousandsSeparator=true;var save=new Button{Text=Localization.Persian?"ذخیره دارو":"Save medicine",Left=405,Top=505,Width=180,Height=40,BackColor=Theme.Teal,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};save.FlatAppearance.BorderSize=0;save.Click+=(s,e)=>Save(m);Controls.Add(save);if(m!=null){fa.Text=m.NameFa;en.Text=m.NameEn;bar.Text=m.Barcode;cat.Text=m.Category;stock.Value=m.Stock;min.Value=m.MinStock;buy.Value=m.BuyPrice;sell.Value=m.SellPrice;expiry.Value=m.Expiry;batch.Text=m.Batch;maker.Text=m.Manufacturer;}}void Save(Medicine old){if(string.IsNullOrWhiteSpace(fa.Text)||string.IsNullOrWhiteSpace(bar.Text)){MessageBox.Show(Localization.Persian?"نام و بارکد الزامی است.":"Name and barcode are required.");return;}Result=old??new Medicine();Result.NameFa=fa.Text.Trim();Result.NameEn=en.Text.Trim();Result.Barcode=bar.Text.Trim();Result.Category=cat.Text.Trim();Result.Stock=(int)stock.Value;Result.MinStock=(int)min.Value;Result.BuyPrice=buy.Value;Result.SellPrice=sell.Value;Result.Expiry=expiry.Value.Date;Result.Batch=batch.Text.Trim();Result.Manufacturer=maker.Text.Trim();DialogResult=DialogResult.OK;Close();}}}
